    static let all: [CreoTheme] = [.mintDark, .contrastDark, .contrastLight, .mintLight, .oldschoolDark, .oldschoolLight, .soraDark, .soraLight]

    /// theme id ("mint-dark" 等) から preset を引く
    static func preset(id: String) -> CreoTheme? {
        all.first { $0.id == id }
    }
}

/// 4 family × light/dark。外観モード追従は .creoTheme(_ family:)
/// (CreoThemeEnvironment.swift) が colorScheme を見て light/dark を選ぶ。
public enum CreoThemeFamily: String, CaseIterable, Sendable {
    case mint
    case contrast
    case oldschool
    case sora

    /// light variant の preset
    public var light: CreoTheme {
        switch self {
        case .mint: return .mintLight
        case .contrast: return .contrastLight
        case .oldschool: return .oldschoolLight
        case .sora: return .soraLight
        }
    }

    /// dark variant の preset
    public var dark: CreoTheme {
        switch self {
        case .mint: return .mintDark
        case .contrast: return .contrastDark
        case .oldschool: return .oldschoolDark
        case .sora: return .soraDark
        }
    }
}
